INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR001', 'Vendor Name Not Null', 'Completeness', 'CRITICAL', 'Vendor master name field must not be null or empty', 'SELECT VENDOR_ID FROM VENDORS WHERE VENDOR_NAME IS NULL OR TRIM(VENDOR_NAME) = ''''', 'Contact vendor to obtain legal name, update master');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR002', 'Tax ID Present For Active', 'Completeness', 'HIGH', 'All ACTIVE vendors must have a tax identification number', 'SELECT VENDOR_ID FROM VENDORS WHERE STATUS = ''ACTIVE'' AND (TAX_ID IS NULL OR TAX_ID = '''')', 'Request tax certificate from vendor, block until received');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR003', 'Bank Account Format', 'Validity', 'HIGH', 'Bank account must be numeric and at least 8 digits', 'SELECT VENDOR_ID FROM VENDORS WHERE LENGTH(BANK_ACCOUNT) < 8', 'Validate with treasury team, update via workflow');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR004', 'Duplicate Vendor Detection', 'Uniqueness', 'HIGH', 'Vendors with same address and similar name likely duplicates', 'SELECT A.VENDOR_ID, B.VENDOR_ID FROM VENDORS A JOIN VENDORS B ON A.ADDRESS_LINE1 = B.ADDRESS_LINE1 AND A.CITY = B.CITY WHERE A.VENDOR_ID < B.VENDOR_ID', 'MDG dedup workflow, merge or archive one record');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR005', 'Blocked Vendor Active Transactions', 'Consistency', 'CRITICAL', 'BLOCKED vendors should not have new transactions posted', 'SELECT T.TXN_ID FROM TRANSACTIONS T JOIN VENDORS V ON T.VENDOR_ID = V.VENDOR_ID WHERE V.STATUS = ''BLOCKED'' AND T.POSTING_DATE > CURRENT_DATE - 90', 'Audit posting, reverse if unauthorized, notify compliance');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR006', 'Missing Country Code', 'Completeness', 'MEDIUM', 'Vendor country ISO code required for tax reporting', 'SELECT VENDOR_ID FROM VENDORS WHERE COUNTRY IS NULL OR LENGTH(COUNTRY) != 3', 'Enrich from address, validate against ISO 3166');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR007', 'Invalid Payment Terms', 'Validity', 'MEDIUM', 'Payment terms must match approved code list', 'SELECT VENDOR_ID FROM VENDORS WHERE PAYMENT_TERMS NOT IN (''NT30'',''NT45'',''NT60'',''NT90'',''2P10'',''IMM'')', 'Update to approved payment term code');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR008', 'High Risk Score Review', 'Consistency', 'HIGH', 'Vendors with risk score above 0.8 require quarterly review', 'SELECT VENDOR_ID FROM VENDORS WHERE RISK_SCORE > 0.8 AND STATUS = ''ACTIVE''', 'Send to procurement risk committee for review');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR009', 'Stale Vendor Records', 'Timeliness', 'LOW', 'Vendors not modified for over 3 years may be inactive', 'SELECT VENDOR_ID FROM VENDORS WHERE LAST_MODIFIED < ADD_YEARS(CURRENT_DATE, -3)', 'Contact for confirmation, archive if no response');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR010', 'Weekend Posting Anomaly', 'Consistency', 'MEDIUM', 'Transactions posted on weekends require justification', 'SELECT TXN_ID FROM TRANSACTIONS WHERE WEEKDAY(POSTING_DATE) IN (5,6)', 'Review posting authorization and business reason');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR011', 'Round Number Amount', 'Consistency', 'MEDIUM', 'Perfectly round transaction amounts are unusual for real invoices', 'SELECT TXN_ID FROM TRANSACTIONS WHERE MOD(AMOUNT, 5000) = 0 AND AMOUNT >= 10000', 'Cross check with PO and receipt, flag if no support');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR012', 'Currency Mismatch', 'Consistency', 'MEDIUM', 'Transaction currency should match vendor default currency', 'SELECT T.TXN_ID FROM TRANSACTIONS T JOIN VENDORS V ON T.VENDOR_ID = V.VENDOR_ID WHERE T.CURRENCY != V.CURRENCY', 'Verify hedging policy, correct FX booking if needed');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR013', 'Postal Code Format', 'Validity', 'LOW', 'Postal code should match country format', 'SELECT VENDOR_ID FROM VENDORS WHERE COUNTRY = ''USA'' AND LENGTH(POSTAL_CODE) != 5', 'Correct via address validation service');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR014', 'New Vendor Rapid Payment', 'Consistency', 'HIGH', 'Vendors created within last 30 days receiving payments over 50k', 'SELECT T.TXN_ID FROM TRANSACTIONS T JOIN VENDORS V ON T.VENDOR_ID = V.VENDOR_ID WHERE V.CREATED_ON > CURRENT_DATE - 30 AND T.AMOUNT > 50000', 'Enhanced due diligence review before payment release');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR015', 'Pending Status Over 60 Days', 'Timeliness', 'MEDIUM', 'Vendors in PENDING status for over 60 days need action', 'SELECT VENDOR_ID FROM VENDORS WHERE STATUS = ''PENDING'' AND CREATED_ON < CURRENT_DATE - 60', 'Complete onboarding or reject application');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR016', 'Category Missing', 'Completeness', 'MEDIUM', 'Vendor category required for spend analytics', 'SELECT VENDOR_ID FROM VENDORS WHERE CATEGORY IS NULL OR CATEGORY = ''''', 'Classify based on invoiced services');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR017', 'Overdue Payment Ratio', 'Consistency', 'HIGH', 'Vendors with over 50% overdue payments indicate cash flow issue', 'SELECT VENDOR_ID FROM TRANSACTIONS WHERE PAYMENT_STATUS = ''OVERDUE'' GROUP BY VENDOR_ID HAVING COUNT(*) > 5', 'Alert AP team to investigate cash and dispute status');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR018', 'Duplicate Invoice Number', 'Uniqueness', 'CRITICAL', 'Same invoice number for same vendor indicates duplicate payment risk', 'SELECT VENDOR_ID, INVOICE_NUMBER FROM TRANSACTIONS GROUP BY VENDOR_ID, INVOICE_NUMBER HAVING COUNT(*) > 1', 'Reverse duplicate payment, recover from vendor');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR019', 'Very Old Invoice Postings', 'Timeliness', 'LOW', 'Invoices posted more than 90 days after invoice date', 'SELECT TXN_ID FROM TRANSACTIONS WHERE DAYS_BETWEEN(INVOICE_DATE, POSTING_DATE) > 90', 'Investigate posting delay, adjust period if needed');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR020', 'Bank Account Sharing', 'Uniqueness', 'HIGH', 'Multiple vendors sharing same bank account is high fraud risk', 'SELECT BANK_ACCOUNT FROM VENDORS GROUP BY BANK_ACCOUNT HAVING COUNT(*) > 1', 'Immediate investigation, freeze payments pending review');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR021', 'Vendor Name Length Anomaly', 'Validity', 'LOW', 'Vendor names shorter than 3 characters or longer than 150 unusual', 'SELECT VENDOR_ID FROM VENDORS WHERE LENGTH(VENDOR_NAME) < 3 OR LENGTH(VENDOR_NAME) > 150', 'Verify legal name, correct or standardize');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR022', 'Description Empty', 'Completeness', 'LOW', 'Vendor description missing hinders searchability', 'SELECT VENDOR_ID FROM VENDORS WHERE DESCRIPTION IS NULL OR LENGTH(DESCRIPTION) < 10', 'Add meaningful description of vendor services');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR023', 'Zero Amount Invoices', 'Validity', 'MEDIUM', 'Zero or negative amount invoices should not exist without credit memo', 'SELECT TXN_ID FROM TRANSACTIONS WHERE AMOUNT <= 0', 'Verify with AP, likely data entry error');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR024', 'Payment To Wrong Country', 'Consistency', 'HIGH', 'Payments to sanctioned or non doing business countries', 'SELECT V.VENDOR_ID FROM VENDORS V WHERE V.COUNTRY IN (''IRN'',''PRK'',''SYR'',''CUB'')', 'Immediate compliance escalation, freeze account');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR025', 'IT Category No IT Description', 'Consistency', 'LOW', 'IT_SERVICES category vendors should mention IT or technology in description', 'SELECT VENDOR_ID FROM VENDORS WHERE CATEGORY = ''IT_SERVICES'' AND UPPER(DESCRIPTION) NOT LIKE ''%IT%'' AND UPPER(DESCRIPTION) NOT LIKE ''%TECHNOLOGY%''', 'Verify category assignment, re-classify if needed');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR026', 'Concentration Risk', 'Consistency', 'MEDIUM', 'Single vendor receiving over 20% of total spend in category', 'WITH SPEND AS (SELECT V.CATEGORY, T.VENDOR_ID, SUM(T.AMOUNT) AS VENDOR_SPEND FROM TRANSACTIONS T JOIN VENDORS V ON T.VENDOR_ID = V.VENDOR_ID GROUP BY V.CATEGORY, T.VENDOR_ID) SELECT VENDOR_ID FROM SPEND WHERE VENDOR_SPEND > 0', 'Review vendor diversification strategy');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR027', 'Rapid Modification Frequency', 'Consistency', 'MEDIUM', 'Vendor master modified within 24 hours of transaction posting suspicious', 'SELECT V.VENDOR_ID FROM VENDORS V JOIN TRANSACTIONS T ON V.VENDOR_ID = T.VENDOR_ID WHERE DAYS_BETWEEN(V.LAST_MODIFIED, T.POSTING_DATE) BETWEEN 0 AND 1', 'Audit master change log for authorization');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR028', 'Address Format Standard', 'Validity', 'LOW', 'Address line missing street number is non standard', 'SELECT VENDOR_ID FROM VENDORS WHERE ADDRESS_LINE1 NOT LIKE ''%[0-9]%''', 'Standardize address via geocoding service');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR029', 'Payment Terms Discount Unused', 'Consistency', 'LOW', 'Vendors with 2P10 terms but no early payments captured', 'SELECT V.VENDOR_ID FROM VENDORS V WHERE V.PAYMENT_TERMS = ''2P10''', 'Route through early payment discount workflow');
INSERT INTO QUALITY_RULES (RULE_ID, RULE_NAME, RULE_CATEGORY, SEVERITY, DESCRIPTION, SQL_CHECK, REMEDIATION) VALUES ('QR030', 'Currency Not Approved', 'Validity', 'MEDIUM', 'Vendor currency must be from approved list', 'SELECT VENDOR_ID FROM VENDORS WHERE CURRENCY NOT IN (''USD'',''EUR'',''GBP'',''INR'',''CNY'',''JPY'',''BRL'',''CAD'',''AUD'')', 'Update to approved currency or add to approved list');
